// Typed Mongo documents. Ids are UUIDv7 strings generated by the app.

export interface UserDoc {
    _id: string;
    email: string | null;
    emailLower: string | null;
    passwordHash: string | null;
    displayName: string;
    isGuest: boolean;
    emailVerifiedAt: Date | null;
    createdAt: Date;
    updatedAt: Date;
    lastSeenAt: Date;
}

export interface SessionDoc {
    _id: string;
    userId: string;
    tokenHash: Buffer;
    createdAt: Date;
    lastUsedAt: Date;
    expiresAt: Date;
    /** Hard cap that sliding expiry cannot extend. */
    absoluteExpiresAt: Date;
    ip: string | null;
    userAgent: string | null;
}

export interface SaveDoc {
    /** Same as the owner's user id. */
    _id: string;
    schemaVersion: 1;
    state: unknown;
    simClock: number;
    lastSimAt: Date;
    revision: number;
    updatedAt: Date;
}

export interface TokenDoc {
    _id: string;
    userId: string;
    purpose: "verify" | "reset";
    tokenHash: Buffer;
    expiresAt: Date;
    usedAt: Date | null;
}

/** The shape returned to clients. Never includes passwordHash. */
export interface PublicUser {
    id: string;
    email: string | null;
    displayName: string;
    isGuest: boolean;
    emailVerified: boolean;
    createdAt: string;
}
